"""Extract traceable register records; output JSON intermediate, never model inputs."""
from pathlib import Path
import csv,json
R=Path(__file__).resolve().parent; U=R/'source_snapshot/upstream'; rows=[]
def add(p,v,unit,key,src,region,asean,used,reason,category='DEFAULT_WITHOUT_ASEAN_EVIDENCE',judgment='ASEAN_VALIDATION_PENDING',year='UNSPECIFIED',transform='As stored; not changed'):
    rows.append(dict(Parameter=p,Value=str(v),Unit=unit,Config_Key=key,Source=src,Source_Region=region,ASEAN_Specific=asean,Used_In_Frozen_SHA=used,Status='UNVERIFIED',Reason=reason,Source_Classification=category,Audit_Judgment=judgment,Reference_Year=year,Transformation=transform,Human_Acceptance='PENDING',Evidence_Layer='F/U; T/P applicability explained in reports',Frozen_SHA='a3616a68ee44592af6527ca9024a90f1956646ae'))
pre='YES: preparation/pre-final-pruning; final heat removed'
add('Demand base year',2019,'year','demand_data.base_year','config.default.yaml; scripts/build_base_energy_totals.py','Global with ASEAN records','Country rows, not heat end-use validation','YES','Raw balance year differs from file export date','RECOVERED_SOURCE','SOURCE_RECOVERED','2019')
add('Space heating share',.6,'fraction','sector.space_heat_share','config.default.yaml:849; history/SPLIT_ORIGINAL_COMMIT.txt','Earth-Sec default','NO',pre,'Common for R/S and all countries; underlying statistical justification not recovered',judgment='REJECT_DEFAULT')
