for table in ['fuel_shares','growth_factors_cagr','efficiency_gains_cagr','district_heating']:
    with (U/f'data/demand/{table}.csv').open(newline='') as fh:
        data=list(csv.DictReader(fh)); default=next(r for r in data if str(next(iter(r.values()))).strip()=='DEFAULT')
    for key,value in list(default.items())[1:]:
        if table in ['growth_factors_cagr','efficiency_gains_cagr'] and not any(k in key for k in ['residential','services']):continue
        used=pre;reason='No ASEAN row: each configured country inherits DEFAULT'
        if table=='district_heating' and key=='potential':used='NO: column not consumed by current heat pathway';reason='Do not confuse this unused column with sector.district_heating.potential'
        add(f'{table}: {key}',value.strip(),'fraction/year' if 'cagr' in table else 'fraction',f'data/demand/{table}.csv:DEFAULT:{key}',f'data/demand/{table}.csv','Default; no established geographic calibration','NO',used,reason,judgment='REJECT_DEFAULT',transform='(1+x)^(planning_year-2019)' if 'cagr' in table else 'Fallback DEFAULT then used in formulas')
for key,value,reason in [('potential',.3,'Fraction of urban heat allocated to central supply'),('progress',1,'Actual formula: 1 reaches target; config comment about -1 inconsistent'),('district_heating_loss',.15,'Adds 15% to delivered heat; not division by 0.85')]:
    add('District heating '+key,value,'fraction','sector.district_heating.'+key,'config.default.yaml:825-834; scripts/prepare_sector_network.py:2552-2735','Inherited Earth-Sec/Earth','NO',pre,reason,judgment='REJECT_DEFAULT')
add('Heat profile','24 x 8 BDEW factors','dimensionless shape','Snakefile.prepare_heat_data.input.heat_profile','data/heat_load_profile_BDEW.csv; evidence/PROFILE_SOURCE_RECOVERY.json','Germany / European model inheritance','NO',pre,'Numeric match to Eur-Sec v0.7.0; exact original generation settings unresolved','EUROPE_SPECIFIC','ASEAN_VALIDATION_PENDING')
add('Water heating hourly shape',1,'constant relative weight','BDEW water columns','data/heat_load_profile_BDEW.csv','Inherited European model template','NO',pre,'All 24 hours, both sectors, weekday and weekend equal 1','EUROPE_SPECIFIC','REJECT_DEFAULT')
for p,v,unit in [('threshold',15,'degC'),('a',1,'relative slope'),('constant',0,'relative demand'),('hour_shift',0,'hours UTC shift')]:
    add('Atlite heat-demand '+p,v,unit,'atlite.heat_demand default (not explicit config)','evidence/installed_atlite_heat_demand.py; scripts/build_heat_demand.py','Generic degree-day model','NO','Implicit in U script; observed installed atlite 0.4.1','Dependency default; author original environment not asserted','RECOVERED_SOURCE','ASEAN_VALIDATION_PENDING',transform='daily max(15-temperature_C,0) with a=1, constant=0')
add('BDEW timezone','first national pytz timezone','timezone rule','generate_periodic_profiles','scripts/prepare_heat_data.py','Country-selected, one timezone','PARTIAL',pre,'Multiple-timezone countries not resolved by node','RECOVERED_SOURCE','ENGINEERING_ISSUE')
