add('Population raster year',2020,'year','build_shape_options.year','evidence/CONFIG_LAYERS.json; scripts/build_shapes.py','WorldPop global','PARTIAL',pre,'Country coverage is not building demand validation','RECOVERED_SOURCE','ASEAN_VALIDATION_PENDING','2020')
add('Urban population fraction','country / horizon series','fraction','prepare_urban_percent; pop_layout.urban','scripts/prepare_urban_percent.py; UNCTAD US.PopTotal','Global, country specific','Country rows',pre,'Public live API; download version not pinned; spatial split by density','RECOVERED_SOURCE','ASEAN_VALIDATION_PENDING')
add('Base load spatial weights','GDP 0.6; population 0.4','relative weights','build_demand_profiles.upsample','scripts/build_demand_profiles.py:399-418','EU regression per source comment','NO','YES base-profile spatial allocation','Different allocation from annual heat; no ASEAN regression','EUROPE_SPECIFIC','ASEAN_VALIDATION_PENDING')
add('Existing heating stock','EU28+3; ASEAN absent; DEFAULT blanks -> 0','GW raw; MW prepared','build_existing_heating_distribution','data/existing_infrastructure/existing_heating_raw.csv; EC WP2 201603','Europe','NO','Preparation only; baseyear call commented','Zero is fallback, not observed ASEAN capacity','EUROPE_SPECIFIC','REJECT_DEFAULT','2012',transform='fillna(0); x1000; population and heat-sector fraction')
add('Existing stock urban fraction','pop_layout.fraction','national node share used as urban share','build_existing_heating_distribution','scripts/build_existing_heating_distribution.py:114','Code logic','NO','Dormant capacity insertion; preparation path exists','Wrong semantic field','RECOVERED_SOURCE','ENGINEERING_ISSUE')
add('Existing heating default lifetime',20,'years','existing_capacities.default_heating_lifetime','config.default.yaml:713; scripts/add_existing_baseyear.py','Inherited default','NO','NO active insertion: main call commented','Historical grouping not validated for ASEAN','RECOVERED_SOURCE','SCIENTIFIC_DECISION_REQUIRED')
add('HP sink temperature',55,'degC','sector.heat_pump_sink_T','config.default.yaml:868; scripts/build_cop_profiles.py','DTU / large-area radiators comment','NO',pre,'Staffell 2012 quadratic COP; not reversible cooling','EUROPE_SPECIFIC','ASEAN_VALIDATION_PENDING')
for p,v,unit in [('tes_tau.decentral',3,'days'),('tes_tau.central',180,'days'),('solar_thermal_collector.cf_correction',.788457,'multiplier'),('solar_thermal_collector.orientation.slope',45,'degrees'),('solar_thermal_collector.orientation.azimuth',180,'degrees')]:
    add(p,v,unit,'sector.'+p,'config.default.yaml:851-869','Inherited default','NO',pre,'Affects competition and profiles; no ASEAN validation recovered')
add('Explicit building cooling','absent','component boundary','No cooling switch','history/COOLING_CODE_SEARCH.txt; scripts/prepare_sector_network.py','Model structure','NOT APPLICABLE','No independent cooling component','Aggregate electricity cooling content unquantified','RECOVERED_SOURCE','SCIENTIFIC_DECISION_REQUIRED')
add('Electric heat subtraction','commented out','accounting operation','prepare_heat_data electric_heat_supply','scripts/prepare_heat_data.py:201-220','Model structure','NOT APPLICABLE','NO active subtraction','Quantity not returned/exported; no accepted existing electric-heat bridge','RECOVERED_SOURCE','ENGINEERING_ISSUE')
add('Final electricity-only pruning','true','boolean','final_adjustment.only_elec_network','configs/config.asean.yaml:262','ASEAN configuration','Config specific, not data validation','YES: final heat removed','All three layers U/T/P true; not a full-SC scientific baseline','RECOVERED_SOURCE','ENGINEERING_ISSUE')
(R/'ASSUMPTION_RECORDS.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
print(f'{len(rows)} records, all UNVERIFIED')
